ALTER TABLE purchase_orders ENABLE TRIGGER trg_purchase_orders_set_updated_at;

-- Document numbers were issued explicitly: move the counters to the highest number of each year.
UPDATE number_ranges SET last_value = 336
 WHERE document_type = 'goods_receipt' AND fiscal_year = 2025;
UPDATE number_ranges SET last_value = 1189
 WHERE document_type = 'goods_receipt' AND fiscal_year = 2026;

-- Sequences continue after the explicit ids.
SELECT setval(pg_get_serial_sequence('goods_receipts', 'id'), (SELECT max(id) FROM goods_receipts));
SELECT setval(pg_get_serial_sequence('goods_receipt_items', 'id'), (SELECT max(id) FROM goods_receipt_items));

DO $$
DECLARE
    t record;
BEGIN
    FOR t IN
        SELECT tgrelid::regclass AS table_name, tgname
          FROM pg_trigger
         WHERE tgfoid = 'audit_row_change'::regproc
           AND NOT tgisinternal
    LOOP
        EXECUTE format('ALTER TABLE %s ENABLE TRIGGER %I', t.table_name, t.tgname);
    END LOOP;
END;
$$;

COMMIT;
